BEGIN;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL standard_conforming_strings = on;
SET LOCAL lock_timeout = '30s';

-- EduMap | Directorio de la ciudad de Arequipa | 24/11/2026
-- Carga: 1296 instituciones, 1376 sedes y 133 registros de sede pendientes. Requiere las 22 tablas y la vista del equipo en el esquema public.
-- Ejecutar: psql -X -v ON_ERROR_STOP=1 -P pager=off -d BASE -f edumap_arequipa.sql
-- La carga reutiliza registros identificados de forma inequívoca y agrega los faltantes.
--
-- Fuentes del directorio
-- MINEDU–ESCALE, Padrón de Servicios Educativos, 17/11/2026, Padron_web.dbf.
-- https://escale.minedu.gob.pe/documents/10156/958881/Padron_web_20261117.zip?version=1.0
-- SHA-256 ZIP: FAA812B0594667DC06D7131C3274D0D1BCDE25B0EFE6E7E7197773F44324996E
-- DIGESUTPA, listado de institutos licenciados, corte 23/06/2026 (publicado 01/07).
-- https://www.gob.pe/institucion/minedu/informes-publicaciones/4718331-lista-de-223-institutos-de-educacion-superior-licenciadas-por-minedu
-- SUNEDU, Programas de Universidades_9.csv, FECHA_CORTE 2024-08-28 (archivo entregado).
-- https://www.datosabiertos.gob.pe/dataset/sunedu-programas-acad%C3%A9micos
-- SHA-256 CSV: 83c2f6296cdbf99817895b09d2d1d08b074e03efdbe3a221a46c7f362595df89
-- Vigencia institucional contrastada con https://www.sunedu.gob.pe/lista-de-universidades-licenciadas/
-- Direcciones de los locales y excepciones a las coordenadas del CSV:
-- UNSA (005), RCD 098-2018 y puntos de su directorio oficial para SL01/SL02/SL03.
-- https://cdn.www.gob.pe/uploads/document/file/1257646/res-098-2018-sunedu-cd-anexo-resuelve-aprobar-el-licenciamiento-institucional-unsa.pdf
-- https://www.gob.pe/institucion/universidad-nacional-de-san-agustin/sedes
-- UCSM (015) https://busquedas.elperuano.pe/dispositivo/NL/2071821-1
-- USMP (019) https://usmp.edu.pe/directorio-usmp/
-- UCSP (062) https://busquedas.elperuano.pe/dispositivo/NL/1897582-1
-- UCSP SL03 https://cdn.www.gob.pe/uploads/document/file/3850054/ITML.pdf
-- UTP (065) https://busquedas.elperuano.pe/dispositivo/NL/1986910-1
-- Continental (067) https://cdn.www.gob.pe/uploads/document/file/2936159/Resoluci%C3%B3n.pdf
-- La Salle (133) https://www.gob.pe/institucion/sunedu/normas-legales/2783830-016-2022-sunedu-cd
-- USIL (057), RCD 0023-2026, posterior al CSV. Punto del complejo Parque Lambramani,
-- referenciado por SEAL en la pág. 7 de su plan 2024 a escala del predio.
-- https://busquedas.elperuano.pe/dispositivo/NL/2539374-1
-- https://www.seal.com.pe/compania/Documentos%20compartidos/Plan%20de%20continuidad%20operativa%20oct%202024.pdf
--
-- Correcciones de locales MINEDU contrastadas con el establecimiento y su mapa:
-- María Montessori (856597), https://instituto.ismontessori.edu.pe/contact/
-- https://www.waze.com/live-map/directions/pe/arequipa/miraflores/instituto-montessori?to=place.ChIJT5ZmD0ZLQpEReODEXYzsE08
-- CERTUS, códigos 846457 y 864031 para el mismo predio. Se carga una sede (846457).
-- https://www.minedu.gob.pe/superiortecnologica/pdf/ie-licenciadas/rm-n-202-2019.pdf
-- https://www.waze.com/es-419/live-map/directions/pe/arequipa/arequipa/certus-arequipa?to=place.ChIJfa6awlRKQpERpcbxRy04ZYQ
-- Toulouse Lautrec (866370), pin de su página de sede, centro distinto de CERTUS.
-- https://www.toulouselautrec.edu.pe/pregrado/carreras-arequipa/
-- Zegel (863588), https://zevirtual.exd.pe/sedes/arequipa
-- https://www.waze.com/live-map/directions/pe/arequipa/cayma/zegel-arequipa?to=place.ChIJEeoAUtFLQpERJUNfA2wzG-c
-- IDAT (868265), dirección y UBIGEO en https://www.idat.edu.pe/campus/arequipa
-- IDAT (864903) se conserva como pendiente del mismo instituto.
-- BSG Institute (865479), https://proceso-seleccion.bsginstitute.com/termino-uso-web
-- https://www.waze.com/live-map/directions/pe/arequipa/arequipa/bsg-institute?to=place.ChIJj0On-2BKQpERnViKeZmBM_o
--
-- Perímetro operativo del continuo urbano, con insumos consultados el 24/11/2026:
-- GHS-UCDB R2024A, época 2025, centro Arequipa ID_UC_G0=3440, elaboración JRC/UE.
-- https://human-settlement.emergency.copernicus.eu/datasets.php
-- https://services2.arcgis.com/jUpNdisbWqRpMo35/arcgis/rest/services/Urban_Center_Database_2025_Geography_Climate/FeatureServer/0
-- SHA-256 GeoJSON de la consulta en EPSG:4326: cbe68376a5badaa749f9dbfc48ad6eadccea1cb4654b867e9f423d35682b7365
-- Unión con los cascos urbanos IGN 1:100 000 que superponen al menos la mitad de
-- su área y 0.25 km² con el centro JRC. Área resultante ≈165.91 km² en UTM 19S.
-- OBJECTID IGN: 859, 861, 865, 875, 880, 882, 883, 884, 885, 886, 887, 888, 891, 894, 895, 898, 899, 900, 901.
-- https://www.idep.gob.pe/geoportal/rest/services/DATOS_GEOESPACIALES/PERU_100K/MapServer/11
-- Límites censales referenciales INEI 2024, publicados por SERFOR, usados para UBIGEO.
-- https://geo.serfor.gob.pe/geoservicios/rest/services/Visor/Limites_Politicos_Administrativos/MapServer/2
-- PDM IMPLA 2016–2025, referencia municipal para distinguir ciudad, provincia y expansión.
-- https://muniarequipa.gob.pe/descargas/transparencia/pdm/memoria/MEMORIA%20PLAN%202016-2025%20CAPITULO%201.pdf
-- Prefiltro provincial 0401. Se exigió punto cubierto por el perímetro y dirección.
-- En ESCALE, se revisa el borde exterior hasta 1 km y la discrepancia distrital >150 m.
-- Los puntos repetidos con direcciones distintas y los casos rurales sin respaldo IGN quedan pendientes.
-- Los puntos de distritos se calcularon dentro de su intersección urbana con el perímetro.
-- Se incluyen servicios activos de básica escolarizada, alternativa y especial, e
-- institutos/escuelas superiores no universitarias. Quedan fuera PRONOEI y CETPRO.
--
-- Se agrupa por CODINST o, sin él, por servicio modular y coincidencia de local,
-- nombre, gestión y familia educativa. Los locales se conservan por CODLOCAL.
-- Para universidades se usan CODIGO_ENTIDAD y CODIGO_LOCAL, sin duplicar por programa.
-- Se guarda un código modular por institución. Los demás quedan en la tabla temporal
-- de trazabilidad, con nivel, anexo, local y estado. Los RUC compartidos quedan en
-- NULL en las fichas nuevas y se enumeran debajo con el valor oficial y las claves relacionadas.
-- La sede principal es la de referencia en el directorio de la ciudad.
-- Sin pensiones verificadas en estos padrones, se omiten las ofertas.
-- La vista devuelve 0.00 para ambas pensiones sin ofertas. Ese 0.00 no confirma gratuidad.
-- La vista y el filtro distrital muestran la sede principal de cada institución.

CREATE TEMP TABLE edumap_aqp_distritos (
    ubigeo char(6) PRIMARY KEY,
    nombre varchar(80) NOT NULL,
    latitud numeric(10,8) NOT NULL,
    longitud numeric(11,8) NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE edumap_aqp_instituciones (
    clave text PRIMARY KEY,
    categoria varchar(50) NOT NULL,
    gestion varchar(50) NOT NULL,
    regulador varchar(20) NOT NULL,
    nombre varchar(150) NOT NULL,
    codigo_modular varchar(25) UNIQUE,
    ruc char(11) UNIQUE,
    descripcion text NOT NULL,
    sitio_web varchar(255)
) ON COMMIT DROP;

CREATE TEMP TABLE edumap_aqp_sedes (
    clave text NOT NULL REFERENCES edumap_aqp_instituciones,
    codigo_local text NOT NULL,
    ubigeo char(6) NOT NULL REFERENCES edumap_aqp_distritos,
    nombre varchar(100) NOT NULL,
    direccion varchar(255) NOT NULL,
    latitud numeric(10,8) NOT NULL CHECK (latitud BETWEEN -17 AND -16),
    longitud numeric(11,8) NOT NULL CHECK (longitud BETWEEN -72 AND -71),
    es_principal boolean NOT NULL,
    fuente text NOT NULL,
    PRIMARY KEY (clave, codigo_local)
) ON COMMIT DROP;

CREATE TEMP TABLE edumap_aqp_modulares (
    clave text NOT NULL REFERENCES edumap_aqp_instituciones,
    codinst text,
    codigo_modular varchar(25) NOT NULL,
    anexo text NOT NULL,
    codigo_local text NOT NULL,
    nivel text NOT NULL,
    estado text NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE edumap_aqp_ruc_pendientes (
    clave text NOT NULL REFERENCES edumap_aqp_instituciones,
    ruc_fuente char(11) NOT NULL,
    motivo text NOT NULL,
    claves_escale text NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE edumap_aqp_pendientes (
    clave text NOT NULL,
    codigo_local text NOT NULL,
    categoria text NOT NULL,
    nombre text NOT NULL,
    ubigeo char(6) NOT NULL,
    direccion_fuente text,
    latitud_fuente numeric(10,8),
    longitud_fuente numeric(11,8),
    motivo text NOT NULL,
    PRIMARY KEY (clave, codigo_local)
) ON COMMIT DROP;




-- Códigos de servicio ESCALE por sede, nivel y anexo.

-- RUC fuente que la restricción UNIQUE no representa en las fichas.

-- Registros de sedes omitidos por falta de confirmación.

-- La exclusión mutua protege las identidades que carecen de una restricción UNIQUE.
LOCK TABLE public.categorias_institucion, public.tipos_gestion, public.entidades_reguladoras,
           public.distritos, public.instituciones, public.sedes_institucion
    IN SHARE ROW EXCLUSIVE MODE;

CREATE OR REPLACE FUNCTION pg_temp.edumap_aqp_norm(valor text)
RETURNS text
LANGUAGE sql IMMUTABLE STRICT
AS $$
    SELECT trim(regexp_replace(
        translate(lower(valor), 'áéíóúüñ', 'aeiouun'), '[^a-z0-9]+', ' ', 'g'
    ))
$$;

VALUES ('Colegio', 'Educación básica'),
       ('Instituto', 'Educación superior no universitaria'),
       ('Universidad', 'Educación superior universitaria')
ON CONFLICT (nombre_categoria) DO NOTHING;

SELECT DISTINCT gestion FROM edumap_aqp_instituciones
ON CONFLICT (nombre_gestion) DO NOTHING;

VALUES ('MINEDU', 'Ministerio de Educación'),
       ('SUNEDU', 'Superintendencia Nacional de Educación Superior Universitaria')
ON CONFLICT (siglas) DO NOTHING;

SELECT d.ubigeo,
       CASE WHEN EXISTS (
           SELECT 1 FROM public.distritos AS existente
           WHERE existente.nombre_distrito = d.nombre AND existente.ubigeo <> d.ubigeo
       ) THEN d.nombre || ' (' || trim(d.ubigeo) || ')' ELSE d.nombre END,
       d.latitud, d.longitud
FROM edumap_aqp_distritos AS d
ON CONFLICT (ubigeo) DO NOTHING;

CREATE TEMP TABLE edumap_aqp_referencias ON COMMIT DROP AS
SELECT s.*, c.id_categoria, t.id_tipo_gestion, e.id_reguladora
FROM edumap_aqp_instituciones AS s
JOIN public.categorias_institucion AS c ON c.nombre_categoria = s.categoria
JOIN public.tipos_gestion AS t ON t.nombre_gestion = s.gestion
JOIN public.entidades_reguladoras AS e ON e.siglas = s.regulador;

CREATE TEMP TABLE edumap_aqp_locales ON COMMIT DROP AS
SELECT s.*, d.id_distrito, pg_temp.edumap_aqp_norm(s.direccion) AS direccion_normalizada
FROM edumap_aqp_sedes AS s
JOIN public.distritos AS d USING (ubigeo);

-- Reutilizar códigos modulares, incluso si la base guardó otro nivel del mismo colegio.
CREATE TEMP TABLE edumap_aqp_ids ON COMMIT DROP AS
WITH instituciones_existentes AS MATERIALIZED (
    SELECT i.*, pg_temp.edumap_aqp_norm(i.nombre) AS nombre_normalizado
    FROM public.instituciones AS i
),
nombres_fuente AS MATERIALIZED (
    SELECT r.*, pg_temp.edumap_aqp_norm(r.nombre) AS nombre_normalizado
    FROM edumap_aqp_referencias AS r
),
candidatas AS (
    SELECT m.clave, i.id_institucion
    FROM edumap_aqp_modulares AS m
    JOIN instituciones_existentes AS i ON i.codigo_modular = m.codigo_modular

    UNION

    SELECT n.clave, i.id_institucion
    FROM nombres_fuente AS n
    JOIN instituciones_existentes AS i USING (nombre_normalizado)
    WHERE i.id_categoria = n.id_categoria
      AND (n.categoria = 'Universidad' OR (
          i.codigo_modular IS NULL
          AND EXISTS (
              SELECT 1
              FROM edumap_aqp_locales AS s
              JOIN public.sedes_institucion AS e ON e.id_institucion = i.id_institucion
                   AND e.id_distrito = s.id_distrito
              WHERE s.clave = n.clave
                AND (e.nombre_sede = s.nombre OR (
                    pg_temp.edumap_aqp_norm(e.direccion) = s.direccion_normalizada
                    AND abs(e.latitud - s.latitud) <= 0.0005
                    AND abs(e.longitud - s.longitud) <= 0.0005
                ))
          )
      ))
)
SELECT clave, id_institucion FROM candidatas;

DO $$
DECLARE
    conflicto text;
BEGIN
    SELECT string_agg(clave, ', ' ORDER BY clave) INTO conflicto
    FROM (
        SELECT clave FROM edumap_aqp_ids GROUP BY clave HAVING count(*) > 1
        UNION
        SELECT i.clave FROM edumap_aqp_ids AS i
        JOIN edumap_aqp_ids AS j USING (id_institucion)
        WHERE i.clave <> j.clave
    ) AS coincidencias;
    IF conflicto IS NOT NULL THEN
        RAISE EXCEPTION 'Coincidencias ambiguas de instituciones existentes: %', conflicto;
    END IF;
END;
$$;

ALTER TABLE edumap_aqp_ids ADD PRIMARY KEY (clave);
ALTER TABLE edumap_aqp_ids ADD UNIQUE (id_institucion);

-- Un RUC ya ocupado se informa al final y no se reasigna.
WITH nuevas AS (
        id_categoria, id_tipo_gestion, id_reguladora,
        nombre, codigo_modular, ruc, descripcion, sitio_web
    )
    SELECT s.id_categoria, s.id_tipo_gestion, s.id_reguladora,
           s.nombre, s.codigo_modular,
           CASE WHEN EXISTS (
               SELECT 1 FROM public.instituciones AS i WHERE i.ruc = s.ruc
           ) THEN NULL ELSE s.ruc END,
           s.descripcion, s.sitio_web
    FROM edumap_aqp_referencias AS s
    WHERE NOT EXISTS (SELECT 1 FROM edumap_aqp_ids AS i WHERE i.clave = s.clave)
    ORDER BY s.clave
    RETURNING id_institucion, id_categoria, codigo_modular, nombre
)
SELECT s.clave, n.id_institucion
FROM nuevas AS n
JOIN edumap_aqp_referencias AS s ON n.id_categoria = s.id_categoria
    AND (n.codigo_modular = s.codigo_modular OR (
        s.codigo_modular IS NULL AND n.codigo_modular IS NULL AND n.nombre = s.nombre
    ));

-- El nombre de sede conserva el código oficial. Para sedes preexistentes se
-- admite la misma dirección en el mismo distrito con puntos cercanos.
CREATE TEMP TABLE edumap_aqp_sedes_ids ON COMMIT DROP AS
SELECT s.clave, s.codigo_local, e.id_sede
FROM edumap_aqp_locales AS s
JOIN edumap_aqp_ids AS i USING (clave)
JOIN public.sedes_institucion AS e ON e.id_institucion = i.id_institucion
    AND (e.nombre_sede = s.nombre OR (
        e.id_distrito = s.id_distrito
        AND pg_temp.edumap_aqp_norm(e.direccion) = s.direccion_normalizada
        AND abs(e.latitud - s.latitud) <= 0.0005
        AND abs(e.longitud - s.longitud) <= 0.0005
        AND NOT EXISTS (
            SELECT 1 FROM edumap_aqp_sedes AS otra
            WHERE otra.clave = s.clave AND otra.nombre = e.nombre_sede
        )
    ));

DO $$
DECLARE
    conflicto text;
BEGIN
    SELECT string_agg(clave || '/' || codigo_local, ', ' ORDER BY clave, codigo_local)
    INTO conflicto
    FROM (
        SELECT clave, codigo_local FROM edumap_aqp_sedes_ids
        GROUP BY clave, codigo_local HAVING count(*) > 1
        UNION
        SELECT a.clave, a.codigo_local FROM edumap_aqp_sedes_ids AS a
        JOIN edumap_aqp_sedes_ids AS b USING (id_sede)
        WHERE (a.clave, a.codigo_local) <> (b.clave, b.codigo_local)
    ) AS coincidencias;
    IF conflicto IS NOT NULL THEN
        RAISE EXCEPTION 'Coincidencias ambiguas de sedes existentes: %', conflicto;
    END IF;
END;
$$;

ALTER TABLE edumap_aqp_sedes_ids ADD PRIMARY KEY (clave, codigo_local);
ALTER TABLE edumap_aqp_sedes_ids ADD UNIQUE (id_sede);

WITH nuevas AS (
        id_institucion, id_distrito, nombre_sede, direccion, latitud, longitud, es_principal
    )
    SELECT i.id_institucion, s.id_distrito, s.nombre, s.direccion, s.latitud, s.longitud,
           s.es_principal AND NOT EXISTS (
               SELECT 1 FROM public.sedes_institucion AS existente
               WHERE existente.id_institucion = i.id_institucion AND existente.es_principal
           )
    FROM edumap_aqp_locales AS s
    JOIN edumap_aqp_ids AS i USING (clave)
    WHERE NOT EXISTS (
        SELECT 1 FROM edumap_aqp_sedes_ids AS e
        WHERE e.clave = s.clave AND e.codigo_local = s.codigo_local
    )
    ORDER BY s.clave, s.codigo_local
    RETURNING id_sede, id_institucion, nombre_sede
)
SELECT s.clave, s.codigo_local, n.id_sede
FROM edumap_aqp_locales AS s
JOIN edumap_aqp_ids AS i USING (clave)
JOIN nuevas AS n ON n.id_institucion = i.id_institucion AND n.nombre_sede = s.nombre;

DO $$
BEGIN
    IF (SELECT count(*) FROM edumap_aqp_ids) <>
       (SELECT count(*) FROM edumap_aqp_instituciones)
       OR (SELECT count(*) FROM edumap_aqp_sedes_ids) <>
          (SELECT count(*) FROM edumap_aqp_sedes) THEN
        RAISE EXCEPTION 'La carga no resolvió todos los identificadores de institución y sede';
    END IF;
END;
$$;

-- Totales de la carga y diagnóstico. Los pendientes no ingresan al directorio.
SELECT i.categoria, i.gestion, count(DISTINCT i.clave) AS instituciones, count(*) AS sedes
FROM edumap_aqp_instituciones AS i
JOIN edumap_aqp_sedes_ids USING (clave)
GROUP BY i.categoria, i.gestion
ORDER BY i.categoria, i.gestion;

SELECT categoria, clave, codigo_local, nombre, ubigeo, direccion_fuente,
       latitud_fuente, longitud_fuente, motivo
FROM edumap_aqp_pendientes
ORDER BY categoria, nombre, codigo_local;

SELECT i.nombre, r.clave, r.ruc_fuente, r.motivo, r.claves_escale
FROM edumap_aqp_ruc_pendientes AS r
JOIN edumap_aqp_instituciones AS i USING (clave)
UNION ALL
SELECT s.nombre, s.clave, s.ruc, 'La ficha existente o su RUC requieren revisión', NULL
FROM edumap_aqp_instituciones AS s
JOIN edumap_aqp_ids AS m USING (clave)
JOIN public.instituciones AS i ON i.id_institucion = m.id_institucion
WHERE s.ruc IS NOT NULL AND i.ruc IS DISTINCT FROM s.ruc
ORDER BY 2;

-- La auditoría recoge los códigos adicionales conservados en el archivo.
SELECT i.nombre, i.clave, e.codigo_modular AS codigo_en_edumap,
       array_agg(DISTINCT m.codigo_modular ORDER BY m.codigo_modular) AS codigos_en_escale
FROM edumap_aqp_instituciones AS i
JOIN edumap_aqp_modulares AS m USING (clave)
JOIN edumap_aqp_ids AS id USING (clave)
JOIN public.instituciones AS e ON e.id_institucion = id.id_institucion
GROUP BY i.nombre, i.clave, e.codigo_modular
HAVING count(DISTINCT m.codigo_modular) > 1
ORDER BY i.clave;

SELECT i.clave, i.nombre, count(s.id_sede) FILTER (WHERE s.es_principal) AS sedes_principales
FROM edumap_aqp_instituciones AS i
JOIN edumap_aqp_ids AS m USING (clave)
LEFT JOIN public.sedes_institucion AS s ON s.id_institucion = m.id_institucion
GROUP BY i.clave, i.nombre
HAVING count(s.id_sede) FILTER (WHERE s.es_principal) <> 1
ORDER BY i.clave;

DROP FUNCTION pg_temp.edumap_aqp_norm(text);
COMMIT;
